// Merges the new-batch drafts (263+, from fetch-new-batch.js) into the main
// answers.js sequence, applying a removal set that may span BOTH the
// established main range (1-262) and the new draft range (263+). Survivors
// get compacted into one fresh gap-free 1..N sequence.
//
// Titles come from two different correct sources (learned from the earlier
// answers.js parsing bug — never re-derive titles from a hand-rolled regex
// against the generated file if a structured source is available):
//   - days 1-262: parsed from answers.js's array literal (only push on an
//     actual regex match — no blank placeholder entries)
//   - days 263+: read directly from new-batch-log.json's `display` field
//
// Usage: node merge-new-batch.js 253,265,270,271,276,277,278,279,280

const fs = require('fs');
const path = require('path');

const IMAGES_DIR = path.join(__dirname, '..', '..', 'games', 'muveez', 'images');
const ANSWERS_PATH = path.join(__dirname, '..', '..', 'games', 'muveez', 'answers.js');
const NEW_BATCH_LOG = path.join(__dirname, 'new-batch-log.json');
const STAGING_DIR = path.join(__dirname, 'renumber-staging');

function readCurrentAnswers() {
  const src = fs.readFileSync(ANSWERS_PATH, 'utf8');
  const match = src.match(/export const ANSWERS_366 = \[([\s\S]*)\];/);
  const titles = [];
  match[1].split('\n').forEach((line) => {
    const m = line.match(/^\s*'((?:[^'\\]|\\.)*)',/);
    if (m) titles.push(m[1].replace(/\\'/g, "'")); // only push on an actual match
  });
  return titles; // index 0 = day 1
}

function main() {
  const removeSet = new Set((process.argv[2] || '').split(',').map((s) => parseInt(s.trim(), 10)).filter((n) => !isNaN(n)));
  console.log(`Removing ${removeSet.size} day(s): ${[...removeSet].sort((a, b) => a - b).join(', ')}`);

  const mainTitles = readCurrentAnswers(); // days 1..mainTitles.length
  const newBatch = JSON.parse(fs.readFileSync(NEW_BATCH_LOG, 'utf8')); // days mainTitles.length+1..

  const allDays = [];
  for (let day = 1; day <= mainTitles.length; day++) {
    allDays.push({ day, title: mainTitles[day - 1] });
  }
  newBatch.forEach((entry) => {
    if (entry.status === 'ok') allDays.push({ day: entry.dayNumber, title: entry.display });
  });

  const survivors = allDays.filter((d) => !removeSet.has(d.day));
  console.log(`Survivors: ${survivors.length} (was ${allDays.length})`);

  fs.rmSync(STAGING_DIR, { recursive: true, force: true });
  fs.mkdirSync(STAGING_DIR, { recursive: true });

  survivors.forEach((s, i) => {
    const newDay = i + 1;
    fs.copyFileSync(path.join(IMAGES_DIR, `${s.day}.jpg`), path.join(STAGING_DIR, `${newDay}.jpg`));
  });

  // Clear every old numbered file across the full range (both removed AND
  // survivors — survivors are already safely staged), then move staged
  // files into place.
  const maxOldDay = Math.max(...allDays.map((d) => d.day));
  for (let day = 1; day <= maxOldDay; day++) {
    const p = path.join(IMAGES_DIR, `${day}.jpg`);
    if (fs.existsSync(p)) fs.unlinkSync(p);
  }
  survivors.forEach((s, i) => {
    const newDay = i + 1;
    fs.renameSync(path.join(STAGING_DIR, `${newDay}.jpg`), path.join(IMAGES_DIR, `${newDay}.jpg`));
  });
  fs.rmSync(STAGING_DIR, { recursive: true, force: true });

  const lines = survivors.map((s, i) => {
    const day = i + 1;
    const escaped = s.title.replace(/'/g, "\\'");
    return `  '${escaped}', // day ${day}: ${s.title}`;
  });

  const fileContent = `// Auto-generated by tools/muveez-curation/merge-new-batch.js — do not hand-edit.
// One answer per calendar day-of-year, same indexing as images/<day>.jpg
// (see index.js's dayOfYear() usage).
export const ANSWERS_366 = [
${lines.join('\n')}
];
`;
  fs.writeFileSync(ANSWERS_PATH, fileContent);
  console.log(`Done. answers.js now has ${survivors.length} entries (days 1-${survivors.length}).`);
}

main();
